struct ChargedParameters {bool valid{};float elastic_rate{},dedx{},range{},hard_rate[2]{};};

// Approximate inverse of the monotonic native restricted-range samples.
// Return unsupported for sub-table ranges; never clamp energy to coverage.

struct ChargedLoss {bool valid{},stopped{};float mean{},raw{},deposit{},remaining{};};
// G4VEnergyLossProcess AlongStep accounting with PIXE/subcut disabled as in
// the extraction. Cut and MaxSecondaryEnergy are model-specific: PenIoni
// inherits E below/equal 100keV; MollerBhabha uses E/2 above 100keV.
// Only stopping/range interpolation is approximated here. An over-energy
// fluctuation is handled by the native finalT<=lowestEnergy rule, not redrawn.
template<class Uniform,class Model>inline ChargedLoss sample_charged_loss(const Model& v,float energy,float length,Uniform& uniform) {
    ChargedLoss out;
    if(!std::isfinite(energy)||energy<=0||!std::isfinite(length)||length<0||length>.25f||!(v.lowest_energy>0))return out;
    // Physical termination applies even below the model's 10eV table minimum.
    if(energy<=v.lowest_energy){out.valid=out.stopped=true;out.mean=out.raw=out.deposit=energy;return out;}
    const auto p=charged_parameters(v,energy);if(!p.valid)return out;
    if(length>=p.range){out.valid=out.stopped=true;out.mean=out.raw=out.deposit=energy;return out;}
    if(length==0){out.valid=true;out.remaining=energy;return out;}
    out.mean=length*p.dedx;
    if(out.mean>v.linear_loss_limit*energy){
        const float remaining=charged_inverse_range(v,p.range-length);
        if(!std::isfinite(remaining))return out;
        const float loss=energy-remaining;if(loss>0)out.mean=loss;
    }
    out.raw=out.mean;
    if(out.mean>=energy)out.raw=energy;
    else {
        const float tmax=energy<=.1f?energy:.5f*energy;
        const auto sampled=sample_electron_urban_loss(v.urban,energy,out.mean,std::min(v.electron_cut,tmax),uniform);
        if(!sampled.valid)return out;out.raw=sampled.loss;
    }
    const float final_energy=energy-out.raw;
    if(final_energy<=v.lowest_energy){out.deposit=energy;out.remaining=0;out.stopped=true;}
    else {out.deposit=out.raw;out.remaining=final_energy;}
    out.valid=true;return out;
}
template<class Uniform,class Model>inline ChargedLoss sample_charged_loss_prepared(const Model& v,float energy,float length,Uniform& uniform,const ChargedParameters& p) {
    ChargedLoss out;
    if(!std::isfinite(energy)||energy<=0||!std::isfinite(length)||length<0||length>.25f||!(v.lowest_energy>0))return out;
    // Physical termination applies even below the model's 10eV table minimum.
    if(energy<=v.lowest_energy){out.valid=out.stopped=true;out.mean=out.raw=out.deposit=energy;return out;}
    if(!p.valid)return out;
    if(length>=p.range){out.valid=out.stopped=true;out.mean=out.raw=out.deposit=energy;return out;}
    if(length==0){out.valid=true;out.remaining=energy;return out;}
    out.mean=length*p.dedx;
    if(out.mean>v.linear_loss_limit*energy){
        const float remaining=charged_inverse_range(v,p.range-length);
        if(!std::isfinite(remaining))return out;
        const float loss=energy-remaining;if(loss>0)out.mean=loss;
    }
    out.raw=out.mean;
    if(out.mean>=energy)out.raw=energy;
    else {
        const float tmax=energy<=.1f?energy:.5f*energy;
        const auto sampled=sample_electron_urban_loss(v.urban,energy,out.mean,std::min(v.electron_cut,tmax),uniform);
        if(!sampled.valid)return out;out.raw=sampled.loss;
    }
    const float final_energy=energy-out.raw;
    if(final_energy<=v.lowest_energy){out.deposit=energy;out.remaining=0;out.stopped=true;}
    else {out.deposit=out.raw;out.remaining=final_energy;}
    out.valid=true;return out;
}
struct ChargedCollision {bool valid{};std::int32_t pdg{};float energy{},cosine{};unsigned process{};};

// electron_charged_density.hpp

// Production26 composition response at actual density; no density-node mixing.
struct ChargedDensityModel {
    const electron_composition26::CollisionComposition26* composition26{};
    const electron_composition26::NativeGridRateView* rate26{};
    int section{-1};float density{},electron_cut{},photon_cut{},lowest_energy{},linear_loss_limit{};
    ElectronUrbanMaterial urban{};ElectronElasticView elastic{};
};
// Node descriptions are immutable and outlive this borrowed model. Accept
// pointers explicitly so a temporary view cannot silently leave dangling refs.
inline ChargedDensityModel charged_density_model(const ChargedResponseView* lower,const ChargedResponseView* upper,float density) {
    ChargedDensityModel out;
    if(!lower||!upper||!lower->composition26||!lower->rate26)return out;
    const auto& low=*lower;const auto& high=*upper;if(low.section!=high.section||!std::isfinite(density)||density<low.density_low||density>low.density_high)return out;
        const auto scalar=electron_continuous_scalar(low.composition26->scalar,density,low.composition26->scalar.energy[0]);
        if(!scalar.valid)return out;
        out.section=low.section;out.density=density;out.composition26=low.composition26;
        out.rate26=low.rate26;out.urban=low.urban;out.elastic=low.elastic;
        out.lowest_energy=low.lowest_energy;out.linear_loss_limit=low.linear_loss_limit;
        // Explicit cut-fit approximation constrained to the extracted domain.
        out.electron_cut=std::clamp(scalar.electron_cut,out.rate26[0].cut_low,out.rate26[0].cut_high);
        out.photon_cut=std::clamp(scalar.photon_cut,out.rate26[1].cut_low,out.rate26[1].cut_high);return out;
}
inline float charged_raw_rate(const ChargedDensityModel& m,unsigned process,float energy) {
    if(!m.composition26||!m.rate26||m.section<0||process>=2)return NAN;
    return electron_composition26::native_grid_rate(m.rate26[process],m.density,
        process?m.photon_cut:m.electron_cut,energy);
}
inline ChargedParameters charged_parameters(const ChargedDensityModel& m,float energy) {
    if(!m.composition26)return {};
const auto scalar=electron_continuous_scalar(m.composition26->scalar,m.density,energy);if(!scalar.valid)return {};
        ChargedParameters out;out.valid=true;out.elastic_rate=scalar.elastic_rate;out.dedx=scalar.stopping;out.range=scalar.range;
        for(unsigned p=0;p<2;++p){out.hard_rate[p]=charged_raw_rate(m,p,energy);if(!std::isfinite(out.hard_rate[p]))return {};}
        return out;
}
inline ChargedParameters charged_parameters_certified(const ChargedDensityModel& m,float energy) {
    if(!m.composition26)return {};
const auto scalar=electron_continuous_scalar(m.composition26->scalar,m.density,energy);if(!scalar.valid)return {};
        ChargedParameters out;out.valid=true;out.elastic_rate=scalar.elastic_rate;out.dedx=scalar.stopping;out.range=scalar.range;
        return out;
}
inline float charged_inverse_range(const ChargedDensityModel& m,float range) {
    if(!m.composition26)return NAN;
    return electron_composition26::continuous_inverse_range26(m.composition26->scalar,m.density,range);
}

template<class Uniform,class Model>inline ChargedCollision sample_charged_collision_rng(const Model& m,float energy,unsigned process,Uniform& uniform){
    return sample_charged_collision(m,energy,process,uniform());
}
template<class Uniform>inline ChargedCollision sample_charged_collision_rng(const ChargedDensityModel& m,float energy,unsigned process,Uniform& uniform){
const auto draw=electron_composition26::sample_collision_composition26(*m.composition26,energy,m.electron_cut,m.photon_cut,process,uniform);
        return {draw.valid,draw.pdg,draw.energy,draw.cosine,process};
}

// electron_charged_bank.hpp

struct ChargedBankView {
    const ChargedResponseView* nodes{};const std::array<float,2>* majorants{};unsigned count{};
    const unsigned* section_offsets{};const unsigned* node_order{};
};
struct ChargedDensityBracket {bool valid{};unsigned low{},high{};float fraction{};};
inline ChargedDensityBracket charged_density_bracket(ChargedBankView bank,int section,float density){
    if(!bank.nodes||!bank.node_order||!bank.section_offsets||bank.count!=26||section<0||section>=26||!std::isfinite(density)||density<=0)return {};
    const auto first=bank.section_offsets[section],end=bank.section_offsets[section+1];
    if(first+1!=end||end>bank.count)return {};
    const auto index=bank.node_order[first];const auto& v=bank.nodes[index];
    return {v.composition26&&density>=v.density_low&&density<=v.density_high,index,index,0.f};
}
inline std::array<float,2> charged_density_majorant(ChargedBankView bank,ChargedDensityBracket b,float density){
    std::array<float,2> out{};
    if(!b.valid)return out;
    const auto model=charged_density_model(bank.nodes+b.low,bank.nodes+b.low,density);
    if(!model.composition26||!model.rate26)return out;
    for(unsigned p=0;p<2;++p)out[p]=electron_composition26::native_grid_cut_majorant(
        model.rate26[p],density,p?model.photon_cut:model.electron_cut);
    return out;
}

// electron_charged_step.hpp

struct ChargedFace {
    bool valid{},escaped{};Coordinate distance{};Position position{};
    std::uint64_t voxel{};std::uint8_t section{};float density{};
};
// Actual ray distance to the next voxel face, before sampling any energy loss.
// Exact face ownership; simultaneous corner crossings use all tied axes.
inline ChargedFace next_charged_face(const ElectronCtGeometry& g,
    Position position,std::array<float,3> direction) {
    ChargedFace out;out.position=position;if(!g.density||!g.section)return out;
    std::int64_t cell[3];Coordinate next[3],face[3];float norm=0;bool outward=false;
    for(unsigned k=0;k<3;++k){
        if(!g.bins[k]||!std::isfinite(g.origin[k])||!std::isfinite(g.spacing[k])||g.spacing[k]<=0||!std::isfinite(position[k])||!std::isfinite(direction[k]))return out;
        norm+=direction[k]*direction[k];
        cell[k]=directed_cell(position[k],direction[k],g.origin[k],g.spacing[k],g.bins[k]);
        if(cell[k]==INT64_MIN)return out;
        if(cell[k]<0||cell[k]>=g.bins[k])outward=true;
        face[k]=g.origin[k]+(cell[k]+(direction[k]>0))*g.spacing[k];
        next[k]=direction[k]?(face[k]-position[k])/direction[k]:std::numeric_limits<float>::infinity();
    }
    if(std::abs(norm-1)>32*std::numeric_limits<float>::epsilon())return out;
    if(outward){out.valid=out.escaped=true;return out;}
    out.voxel=(std::uint64_t(cell[2])*g.bins[1]+cell[1])*g.bins[0]+cell[0];out.section=g.section[out.voxel];out.density=g.density[out.voxel];
    if(out.section>=kElectronMaterialCount||!std::isfinite(out.density)||out.density<=0)return out;
    out.distance=std::min(next[0],std::min(next[1],next[2]));if(!std::isfinite(out.distance)||out.distance<=0)return out;
    for(unsigned k=0;k<3;++k)out.position[k]=next[k]==out.distance?face[k]:position[k]+out.distance*direction[k];
    out.valid=true;return out;
}
enum class ChargedStepStatus {invalid,continued,deposited,photon,escaped,coverage_missing};
struct ChargedStep {
    ChargedStepStatus status{ChargedStepStatus::invalid};Position position{};std::array<float,3> direction{};
    float energy{};Coordinate length{};float raw_loss{},physical_deposit{};
    bool face{},elastic{},hard_proposal{},hard_collision{},stopped{};unsigned process{};
};
// Single-energy-weighted-packet step: W remains unchanged. Sample the branch
// using soft-loss/E, then all positive hard parent/child/local outcomes.
// No queue is needed for this unbiased single-branch energy estimator.
// New approximation: elastic rate frozen at pre-step E, with a mean-loss
// limiter (default 0.5%) and explicit single scattering. Convergence and
// native interface-dose validation are required before CT promotion.
// Hard events use a global energy-domain majorant and exact endpoint-rate
// null test, so losing energy cannot request an unsupported hard channel.
template<class Uniform,class Model>inline ChargedStep transport_charged_step(const Model& model,
    const ElectronCtGeometry& geometry,Position start,std::array<float,3> direction,
    float energy,const std::array<float,2>& hard_majorant,Uniform& uniform,
    float maximum_step=.05f,float mean_loss_fraction=.005f) {
    ChargedStep out;out.position=start;out.direction=direction;out.energy=energy;
    if(!std::isfinite(energy)||energy<=0||!std::isfinite(maximum_step)||maximum_step<=0||maximum_step>.25f||!std::isfinite(mean_loss_fraction)||mean_loss_fraction<=0||mean_loss_fraction>.01f)return out;
    const auto face=next_charged_face(geometry,start,direction);if(!face.valid)return out;
    if(face.escaped){out.status=ChargedStepStatus::escaped;return out;}
    // This isolated primitive uses exact native density nodes. Main-runtime
    // density interpolation must be supplied and independently validated.
    if(face.section!=model.section||float(face.density)!=model.density){out.status=ChargedStepStatus::coverage_missing;return out;}
    if(energy<=model.lowest_energy){out.physical_deposit=energy;out.stopped=true;out.status=ChargedStepStatus::deposited;return out;}
    const auto p=charged_parameters_certified(model,energy);
    if(!p.valid){out.status=ChargedStepStatus::coverage_missing;return out;}
    float hard=0;for(unsigned k=0;k<2;++k){
        if(!std::isfinite(hard_majorant[k])||hard_majorant[k]<0)return out;
        hard+=hard_majorant[k];
    }
    const float rate=p.elastic_rate+hard;
    const float u=uniform();if(!std::isfinite(u)||u<=0||u>=1)return out;
    const float flight=-std::log(u)/rate;
    out.length=std::min(std::min(Coordinate(maximum_step),Coordinate(mean_loss_fraction*energy/p.dedx)),std::min(Coordinate(p.range),std::min(face.distance,Coordinate(flight))));
    if(!std::isfinite(out.length)||out.length<=0)return out;
    out.face=out.length==face.distance;
    if(out.face)out.position=face.position;else for(unsigned k=0;k<3;++k)out.position[k]=start[k]+out.length*direction[k];
    const auto loss=sample_charged_loss_prepared(model,energy,out.length,uniform,p);
    if(!loss.valid){out.status=ChargedStepStatus::coverage_missing;return out;}
    out.raw_loss=loss.raw;out.physical_deposit=loss.deposit;out.stopped=loss.stopped;
    const auto branch=uniform();if(!std::isfinite(branch)||branch<0||branch>=1)return out;
    if(branch<loss.deposit/energy||loss.stopped){
        const float along=uniform();if(!std::isfinite(along)||along<0||along>=1)return out;
        for(unsigned k=0;k<3;++k)out.position[k]=start[k]+along*out.length*direction[k];
        out.status=ChargedStepStatus::deposited;return out;
    }
    out.energy=loss.remaining;
    if(out.length!=flight||out.face){out.status=ChargedStepStatus::continued;return out;}
    const float event=uniform();if(!std::isfinite(event)||event<0||event>=1)return out;
    const float choice=event*rate;float cosine,one_minus_cosine;
    if(choice<p.elastic_rate){
        const auto sampled=sample_electron_elastic(model.elastic,out.energy,uniform);if(!sampled.valid)return out;
        cosine=sampled.cosine;one_minus_cosine=sampled.one_minus_cosine;out.elastic=true;
    }else{
        out.hard_proposal=true;out.process=choice<p.elastic_rate+hard_majorant[0]?0:1;
        const float raw_rate=charged_raw_rate(model,out.process,out.energy);if(!std::isfinite(raw_rate))return out;
        const float effective=std::max(0.f,raw_rate);
        if(!std::isfinite(effective)||effective>hard_majorant[out.process])return out;
        const float accept=uniform();if(!std::isfinite(accept)||accept<0||accept>=1)return out;
        if(accept*hard_majorant[out.process]>=effective){out.status=ChargedStepStatus::continued;return out;}
        const auto sampled=sample_charged_collision_rng(model,out.energy,out.process,uniform);
        if(!sampled.valid){out.status=ChargedStepStatus::coverage_missing;return out;}
        out.hard_collision=true;out.energy=sampled.energy;cosine=sampled.cosine;one_minus_cosine=1-cosine;
        if(sampled.pdg==0){out.status=ChargedStepStatus::deposited;return out;}
        if(sampled.pdg==22)out.status=ChargedStepStatus::photon;
    }
    const float azimuth=uniform();if(!std::isfinite(azimuth)||azimuth<0||azimuth>=1)return out;
    const joint_math::V dir{direction[0],direction[1],direction[2]};
    const auto frame=joint_math::azimuth(dir,6.2831853071795864769f*azimuth);
    const auto next=std::sqrt(std::max(0.f,one_minus_cosine*(2-one_minus_cosine)))*frame.u+cosine*dir;const auto normalized=joint_math::unit(next);out.direction={normalized.x,normalized.y,normalized.z};
    if(out.status!=ChargedStepStatus::photon)out.status=ChargedStepStatus::continued;return out;
}

// electron_charged_packet.hpp

template<class Uniform,class Tally>
inline ElectronEnergyPacket transport_independent_charged_packet(ElectronEnergyPacket packet,
    ChargedBankView bank,const ElectronCtGeometry& geometry,Uniform& uniform,Tally& tally){
    tally(0,1);
    const auto face=next_charged_face(geometry,packet.cursor.position,packet.cursor.direction);
    if(!face.valid){
        packet.status=ElectronPacketStatus::invalid;tally(7,1);return packet;}
    if(face.escaped){
        packet.status=ElectronPacketStatus::escaped;return packet;}
    const auto bracket=charged_density_bracket(bank,face.section,face.density);
    if(!bracket.valid){
        packet.status=ElectronPacketStatus::invalid;tally(6,1);return packet;}
    const auto model=charged_density_model(bank.nodes+bracket.low,bank.nodes+bracket.high,face.density);
    const auto result=transport_charged_step(model,geometry,packet.cursor.position,packet.cursor.direction,
        packet.cursor.energy_MeV,charged_density_majorant(bank,bracket,face.density),uniform,.05f,.005f);
    packet.cursor.section=face.section;packet.cursor.density_g_cm3=face.density;packet.cursor.physical_density_g_cm3=face.density;
    packet.cursor.position=result.position;packet.cursor.direction=result.direction;packet.cursor.energy_MeV=result.energy;
    packet.cursor.row=kElectronContinuationEnd;++packet.advances;
    tally(1,result.elastic);tally(2,result.hard_proposal);tally(3,result.hard_collision);tally(4,result.face);tally(5,result.stopped);
    if(result.status==ChargedStepStatus::continued)packet.cursor.pdg=11;
    else if(result.status==ChargedStepStatus::photon){packet.cursor.pdg=22;++packet.photon_children;}
    else if(result.status==ChargedStepStatus::deposited){packet.deposit_position=result.position;packet.status=ElectronPacketStatus::deposited;}
    else if(result.status==ChargedStepStatus::escaped)packet.status=ElectronPacketStatus::escaped;
    else {packet.status=ElectronPacketStatus::invalid;tally(result.status==ChargedStepStatus::coverage_missing?6:7,1);}
    return packet;
}

// photon_optical_transport.hpp

// Straight photon flight integrates one sampled optical depth through actual
// voxel materials. It does not replay a finite source trajectory and never
// assigns energy to an interface. Interaction outcomes are handled separately.
struct PhotonAttenuation { bool valid{}; float per_mm{}; };
enum class PhotonFlightStatus { invalid, interaction, escaped, coverage_missing };
struct PhotonFlight {
    PhotonFlightStatus status{PhotonFlightStatus::invalid};
    Position position{};
    float distance_mm{},remaining_optical_depth{};
    std::uint8_t section{};float density{};
    std::uint64_t voxel_crossings{};
    unsigned failure_reason{};
};
// rates(section, physical_density, energy) must return an independently
// validated attenuation coefficient, including all retained photon processes.
// Optical depth is -log(U), U strictly between zero and one. No new U is drawn
// at a material change: one collision hazard is integrated over the whole ray.
template<class Rates>
inline PhotonFlight transport_photon_optical_depth(const ElectronCtGeometry& g,
    const Position& start,const std::array<float,3>& direction,
    float energy_MeV,float optical_depth,Rates rates) {
    PhotonFlight out;auto invalid=[&](unsigned reason){out.failure_reason=reason;return out;};out.position=start;out.remaining_optical_depth=optical_depth;
    if(!g.density || !g.section || !std::isfinite(energy_MeV) || energy_MeV<=0 ||
       !std::isfinite(optical_depth) || optical_depth<0)return invalid(1);
    std::array<std::int64_t,3> cell{};
    std::array<int,3> sign{};
    Position next{};
    float norm=0;bool outward=false;
    for(unsigned k=0;k<3;++k) {
        if(!g.bins[k] || !std::isfinite(g.origin[k]) || !std::isfinite(g.spacing[k]) || g.spacing[k]<=0 ||
           !std::isfinite(start[k]) || !std::isfinite(direction[k]))return invalid(2);
        norm+=direction[k]*direction[k];
        cell[k]=directed_cell(start[k],direction[k],g.origin[k],g.spacing[k],g.bins[k]);
        if(cell[k]==INT64_MIN)return invalid(3);
        if(cell[k]<0 || cell[k]>=g.bins[k])outward=true;
        sign[k]=(direction[k]>0)-(direction[k]<0);
        next[k]=std::numeric_limits<float>::infinity();
        if(sign[k]) {
            const Coordinate face=g.origin[k]+(cell[k]+(sign[k]>0))*g.spacing[k];
            next[k]=(face-start[k])/direction[k];
            if(next[k]<0 && !outward)return invalid(4);
        }
    }
    if(std::abs(norm-1)>32*std::numeric_limits<float>::epsilon())return invalid(5);
    if(outward){out.status=PhotonFlightStatus::escaped;return out;}
    Coordinate previous=0;
    const auto limit=std::uint64_t(g.bins[0])+g.bins[1]+g.bins[2]+3;
    for(std::uint64_t hop=0;hop<limit;++hop) {
        const auto index=(std::uint64_t(cell[2])*g.bins[1]+cell[1])*g.bins[0]+cell[0];
        out.section=g.section[index];out.density=g.density[index];
        if(out.section>=kElectronMaterialCount || !std::isfinite(out.density) || out.density<=0)return invalid(6);
        const auto coefficient=rates(out.section,out.density,energy_MeV);
        if(!coefficient.valid) {out.status=PhotonFlightStatus::coverage_missing;return out;}
        if(!std::isfinite(coefficient.per_mm) || coefficient.per_mm<0)return invalid(7);
        const Coordinate face=std::min(next[0],std::min(next[1],next[2]));
        const Coordinate segment=face-previous;
        if(!std::isfinite(face) || segment<0)return invalid(8);
        const Coordinate hazard=coefficient.per_mm*segment;
        if(coefficient.per_mm>0 && out.remaining_optical_depth<hazard) {
            const Coordinate distance=previous+out.remaining_optical_depth/coefficient.per_mm;
            for(unsigned k=0;k<3;++k)out.position[k]=start[k]+distance*direction[k];
            out.distance_mm=distance;out.remaining_optical_depth=0;
            out.status=PhotonFlightStatus::interaction;return out;
        }
        out.remaining_optical_depth-=hazard;
        if(!std::isfinite(out.remaining_optical_depth) || out.remaining_optical_depth<0)return invalid(1);
        out.distance_mm=face;
        for(unsigned k=0;k<3;++k)out.position[k]=start[k]+face*direction[k];
        for(unsigned k=0;k<3;++k)if(next[k]==face) {
            // Exact face ownership, not epsilon displacement into a neighbour.
            out.position[k]=g.origin[k]+(cell[k]+(sign[k]>0))*g.spacing[k];
            cell[k]+=sign[k];
            // Accumulating delta drifts away from the represented physical
            // face; a near-exit collision can then be placed outside the CT.
            // Recompute the clock from the same FP32 cell plane and ray origin.
            const Coordinate following_face=g.origin[k]+float(cell[k]+(sign[k]>0))*g.spacing[k];
            next[k]=(following_face-start[k])/direction[k];
        }
        ++out.voxel_crossings;
        for(unsigned k=0;k<3;++k)if(cell[k]<0 || cell[k]>=g.bins[k]) {
            out.status=PhotonFlightStatus::escaped;return out;
        }
        previous=face;
    }
    return out;
}

// photon_response.hpp

struct PhotonRateRow { float energy{},rate[3]{}; };
struct PhotonOutcome { Probability cdf{};float fraction{},cosine{};std::int32_t pdg{},pad{}; };
struct PhotonChannel { std::uint64_t offset{},count{}; };
struct PhotonResponseView {
    const PhotonRateRow* rates{};const float* edges{};
    const PhotonChannel* channels{};const PhotonOutcome* outcomes{};
    std::uint32_t rate_count{},bins{};std::uint64_t outcome_count{};
    int section{-1};float density{},density_low{},density_high{};
};
struct PhotonRates { bool valid{};float rate[3]{},total{}; };
inline PhotonRates photon_rates(PhotonResponseView model,int section,float density,float energy) {
    PhotonRates out;
    if(!model.rates || model.rate_count<2 || section!=model.section || !std::isfinite(density) || density<=0 ||
       !std::isfinite(model.density) || model.density<=0 || !std::isfinite(energy) ||
       energy<model.rates[0].energy || energy>model.rates[model.rate_count-1].energy)return out;
    unsigned lo=0,hi=model.rate_count-1;
    while(lo+1<hi){const auto m=lo+(hi-lo)/2;if(model.rates[m].energy>energy)hi=m;else lo=m;}
    const auto& a=model.rates[lo];const auto& b=model.rates[hi];
    const float f=(energy-a.energy)/(b.energy-a.energy),scale=density/model.density;
    for(unsigned i=0;i<3;++i) {
        out.rate[i]=((1-f)*a.rate[i]+f*b.rate[i])*scale;
        if(!std::isfinite(out.rate[i]) || out.rate[i]<0)return {};
        out.total+=out.rate[i];
    }
    out.valid=std::isfinite(out.total);return out;
}
struct PhotonCollisionDraw {bool valid{};std::int32_t pdg{};float energy{};joint_math::V direction{};unsigned process{};};
// Energy-weighted single-branch estimator. Statistical W is unchanged by this
// function; physical continuation energy is E*f. A pdg=0 outcome deposits W
// exactly at the sampled interaction, never smeared along the photon flight.
// Every positive native branch is retained in the conditional CDF.
inline PhotonCollisionDraw sample_photon_collision(PhotonResponseView model,
    int section,float physical_density,float energy,joint_math::V direction,
    float process_u,Draw outcome_u,float azimuth_u) {
    PhotonCollisionDraw out;
    if(!std::isfinite(process_u)||process_u<0||process_u>=1||!std::isfinite(outcome_u)||outcome_u<0||outcome_u>=1||
       !std::isfinite(azimuth_u)||azimuth_u<0||azimuth_u>=1||
       !std::isfinite(joint_math::dot(direction,direction))||std::abs(joint_math::dot(direction,direction)-1)>32*std::numeric_limits<float>::epsilon())return out;
    // The conditional collision outcomes use exact density nodes for now.
    // Density interpolation of outcomes is a separate, unvalidated extension.
    if(!model.channels||!model.outcomes||!model.edges||!model.bins||
       physical_density!=model.density||energy<model.edges[0]||energy>model.edges[model.bins])return out;
    const auto rates=photon_rates(model,section,physical_density,energy);if(!rates.valid||rates.total<=0)return out;
    const float coin=process_u*rates.total;
    unsigned process=coin<rates.rate[0]?0:(coin<rates.rate[0]+rates.rate[1]?1:2);
    if(rates.rate[process]<=0)return out;
    unsigned lo=0,hi=model.bins;
    while(lo+1<hi){const auto m=lo+(hi-lo)/2;if(model.edges[m]>energy)hi=m;else lo=m;}
    const auto channel=model.channels[3*lo+process];out.process=process;
    if(!channel.count || channel.offset>model.outcome_count || channel.count>model.outcome_count-channel.offset)return out;
    auto a=channel.offset,b=a+channel.count-1;
    while(a<b){const auto m=a+(b-a)/2;if(outcome_u<model.outcomes[m].cdf)b=m;else a=m+1;}
    const auto& selected=model.outcomes[a];
    out.pdg=selected.pdg;out.energy=selected.fraction*energy;
    if(out.pdg!=0) {
        const auto frame=joint_math::azimuth(direction,6.2831853071795864769f*azimuth_u);
        out.direction=joint_math::unit(std::sqrt(std::max(0.f,1-selected.cosine*selected.cosine))*frame.u+selected.cosine*direction);
    }
    out.valid=out.energy>0;return out;
}

// photon_response_bank.hpp

struct PhotonResponseBankView {
    const PhotonResponseView* nodes{};unsigned count{};
    const unsigned* section_offsets{};
};
struct PhotonDensityBracket {bool valid{};unsigned low{},high{};float upper_weight{};};
inline PhotonDensityBracket photon_density_bracket(PhotonResponseBankView bank,int section,float density) {
    if(!bank.nodes||!bank.section_offsets||bank.count!=26||section<0||section>=26||!std::isfinite(density)||density<=0)return {};
    const auto first=bank.section_offsets[section],end=bank.section_offsets[section+1];
    if(first+1!=end||end>bank.count)return {};
    const auto& v=bank.nodes[first];
    return {density>=v.density_low&&density<=v.density_high,first,first,0.f};
}
inline PhotonAttenuation photon_bank_attenuation(PhotonResponseBankView bank,int section,float density,float energy) {
    const auto bracket=photon_density_bracket(bank,section,density);if(!bracket.valid)return {};
    const auto rates=photon_rates(bank.nodes[bracket.low],section,density,energy);
    return {rates.valid,rates.total};
}
enum class IndependentPhotonStatus { invalid, deposited, escaped, electron, coverage_missing };
struct IndependentPhotonResult {
    IndependentPhotonStatus status{IndependentPhotonStatus::invalid};
    Position position{};std::array<float,3> direction{};
    float energy{},physical_density{};
    unsigned node{};std::uint64_t interactions{},voxel_crossings{};
    unsigned failure_reason{};
};
// Photon-only chain. A selected electron returns its complete physical state
// for charged transport. A selected photon child starts a new independent
// flight. No branch is locally deposited merely because it lacks a record.
// The caller retains the original energy weight W through every transition.
template<class Uniform>
inline IndependentPhotonResult transport_independent_photon(PhotonResponseBankView bank,
    const ElectronCtGeometry& geometry,Position position,
    std::array<float,3> direction,float energy,Uniform& uniform) {
    IndependentPhotonResult out;out.position=position;out.direction=direction;out.energy=energy;
    for(unsigned i=0;i<65536;++i) {
        const float u=uniform();if(!std::isfinite(u)||u<=0||u>=1){out.failure_reason=100;return out;}
        auto rates=[&](int section,float rho,float e){return photon_bank_attenuation(bank,section,rho,e);};
        const auto flight=transport_photon_optical_depth(geometry,out.position,out.direction,out.energy,-std::log(u),rates);
        out.position=flight.position;out.voxel_crossings+=flight.voxel_crossings;out.physical_density=flight.density;
        if(flight.status==PhotonFlightStatus::invalid){out.failure_reason=flight.failure_reason?flight.failure_reason:199;return out;}
        if(flight.status==PhotonFlightStatus::escaped){out.status=IndependentPhotonStatus::escaped;return out;}
        if(flight.status==PhotonFlightStatus::coverage_missing){out.status=IndependentPhotonStatus::coverage_missing;return out;}
        const auto bracket=photon_density_bracket(bank,flight.section,flight.density);
        if(!bracket.valid){out.status=IndependentPhotonStatus::coverage_missing;return out;}
        const float density_u=uniform();if(!std::isfinite(density_u)||density_u<0||density_u>=1){out.failure_reason=101;return out;}
        out.node=density_u<bracket.upper_weight?bracket.high:bracket.low;
        const auto model=bank.nodes[out.node];
        // Optical depth uses actual density; conditional final states use the
        // composition calibration law. Retain the degenerate density draw
        // to preserve the established RNG sequence.
        const float process_u=uniform();const auto outcome_u=uniform();const float azimuth_u=uniform();
        const auto draw=sample_photon_collision(model,model.section,model.density,out.energy,
            {out.direction[0],out.direction[1],out.direction[2]},process_u,outcome_u,azimuth_u);
        if(!draw.valid){out.status=IndependentPhotonStatus::coverage_missing;return out;}
        ++out.interactions;
        if(draw.pdg==0){out.status=IndependentPhotonStatus::deposited;return out;}
        out.energy=draw.energy;out.direction={draw.direction.x,draw.direction.y,draw.direction.z};
        if(draw.pdg==11){out.status=IndependentPhotonStatus::electron;return out;}
        if(draw.pdg!=22){out.failure_reason=102;return out;}
    }
    out.failure_reason=103;return out; // iteration cap is a failure, never dose/escape
}

// Actual-cut birth26 output and shared direction construction.
struct ElectronBirthStateSample {Probability cdf{};float energy{},cosine{};};
struct ElectronBirthPartition {bool valid{};float fraction{};unsigned node{};};
inline joint_math::V independent_electron_direction(
    joint_math::V parent,float cosine,float spin) {
    using namespace joint_math;
    const auto frame=azimuth(parent,6.2831853071795864769f*spin);
    return unit(std::sqrt(std::max(0.f,1-cosine*cosine))*frame.u+cosine*parent);
}

// electron_joint_pilot.hpp

struct ElectronJointPilotView {
    joint_math::View model{};
    const joint_math::V* pre{};
    int section{1}; float density{},radius{.05f};
    const ElectronJointPilotView* sections{};
    unsigned section_count{}; bool density_scaling{};
};
// Check the whole possible charged displacement support BEFORE drawing an
// outcome. Outcome-dependent rejection would bias the retained population.
inline bool joint_homogeneous(const ElectronCtGeometry& g,const Position& p,
                              int section,float density,float radius) {
    std::int64_t lo[3],hi[3];
    for(int k=0;k<3;++k) {
        lo[k]=static_cast<std::int64_t>(std::floor((p[k]-radius-g.origin[k])/g.spacing[k]));
        hi[k]=static_cast<std::int64_t>(std::floor((p[k]+radius-g.origin[k])/g.spacing[k]));
        if(lo[k]<0 || hi[k]>=g.bins[k])return false;
    }
    for(auto z=lo[2];z<=hi[2];++z)for(auto y=lo[1];y<=hi[1];++y)for(auto x=lo[0];x<=hi[0];++x) {
        const auto i=(z*g.bins[1]+y)*g.bins[0]+x;
        if(g.section[i]!=section || g.density[i]!=static_cast<float>(density))return false;
    }
    return true;
}
// Counters: eligible, started, advances, fallback, below-table terminal draws,
// deposited, escaped, photon gap, invalid. W stays with the original packet.
template<class Uniform,class Tally>
inline void transport_joint_pilot(ElectronEnergyPacket& packet,
    ElectronJointPilotView pilot,const ElectronMaterialIdentity& material,
    const ElectronCtGeometry& geometry,Uniform& uniform,Tally& tally) {
    using namespace joint_math;
    if(pilot.sections) {
        if(material.section<0 || unsigned(material.section)>=pilot.section_count)return;
        pilot=pilot.sections[material.section];
    }
    const float scale=pilot.density_scaling?pilot.density/material.density_g_cm3:1.f;
    // The bank uses the lowest indexed density per composition. Unsupported
    // nodes never enlarge the source support or silently extrapolate.
    if(!(scale>0 && scale<=1.0000001f))return;
    const float radius=pilot.radius*scale;
    const auto m=pilot.model;
    if(!m.steps || packet.status!=ElectronPacketStatus::active ||
       material.section!=pilot.section || (!pilot.density_scaling && material.density_g_cm3!=pilot.density) ||
       packet.cursor.energy_MeV>m.edges[m.bins]*(1+1e-7f))return;
    tally(0,1);
    if(!joint_homogeneous(geometry,packet.cursor.position,pilot.section,
                          packet.cursor.physical_density_g_cm3,radius))return;
    tally(1,1);
    auto p=PositionVector{packet.cursor.position[0],packet.cursor.position[1],packet.cursor.position[2]};
    auto d=V{packet.cursor.direction[0],packet.cursor.direction[1],packet.cursor.direction[2]};
    float energy=packet.cursor.energy_MeV;
    int cursor=-1,pdg=11;
    Frame original{{1,0,0},{0,1,0},{0,0,1}},target=original;
    auto state=[&]() {
        packet.cursor.position={p.x,p.y,p.z};d=unit(d);packet.cursor.direction={d.x,d.y,d.z};
        packet.cursor.energy_MeV=energy;packet.cursor.pdg=pdg;
    };
    auto invalid=[&]() {state();packet.status=ElectronPacketStatus::invalid;tally(8,1);return;};
    const unsigned iteration_cap=pilot.density_scaling?65536:4096;
    for(unsigned iteration=0;iteration<iteration_cap;++iteration) {
        const bool exact=cursor>=0;
        const GraphStep* g=nullptr;const SampledStep* s=nullptr;Frame sample_frame{};
        if(exact) {
            if(std::uint32_t(cursor)>=m.graph_count)return invalid();
            g=m.graph+cursor;pdg=g->pdg;
            d=rotate(target,project(original,pilot.pre[cursor]));
            if(pdg==22) {
                state();packet.cursor.row=kElectronContinuationEnd;
                return; // physical photon state, no native source flight replay
            }
            if(!g->inside) {
                if(pdg!=22)return invalid();
                // The native source sphere ended. This is missing photon
                // coverage, not evidence that it escaped the actual patient.
                state();packet.status=ElectronPacketStatus::coverage_missing;
                packet.gap=ElectronPacketGap::photon_continuation;tally(7,1);return;
            }
        }else pdg=11;
        if(pdg==11 && (!joint_homogeneous(geometry,{p.x,p.y,p.z},pilot.section,
              packet.cursor.physical_density_g_cm3,radius) || energy>m.edges[m.bins]*(1+1e-7f))) {
            state();tally(3,1);
            packet.cursor.row=kElectronContinuationEnd;return;
        }
        V delta;const float* f;
        if(exact) {delta=rotate(target,project(original,g->delta));f=g->fraction;}
        else {
            if(!(energy>0))return invalid();
            std::uint32_t a=0,b=m.bins;
            while(a<b){const auto mid=a+(b-a)/2;if(m.edges[mid+1]<=energy)a=mid+1;else b=mid;}
            const auto bin=m.nearest[a<m.bins?a:m.bins-1];
            auto lo=m.offsets[bin],hi=m.offsets[bin+1];
            const auto coin=uniform();
            while(lo+1<hi){const auto mid=lo+(hi-lo)/2;if(coin<m.steps[mid-1].cdf)hi=mid;else lo=mid;}
            s=m.steps+lo;
            if(energy<m.edges[0]) {tally(4,1);if(s->fraction[0]<1-1e-7f)return invalid();}
            sample_frame=azimuth(d,6.2831853071795864769f*uniform());
            delta=rotate(sample_frame,s->delta);f=s->fraction;
        }
        delta=scale*delta;
        if(pdg==11 && ((exact?g->length:s->length)*scale>.250001f || dot(delta,delta)>radius*radius))return invalid();
        const auto endpoint=p+delta;
        if(pdg==22) {
            const auto boundary=first_electron_ct_boundary(geometry,{p.x,p.y,p.z},{endpoint.x,endpoint.y,endpoint.z});
            if(boundary.status==ElectronCtBoundaryStatus::invalid)return invalid();
            if(boundary.status!=ElectronCtBoundaryStatus::contained) {
                p={boundary.position[0],boundary.position[1],boundary.position[2]};state();
                if(boundary.status==ElectronCtBoundaryStatus::escaped){packet.status=ElectronPacketStatus::escaped;tally(6,1);}
                else {packet.status=ElectronPacketStatus::coverage_missing;packet.gap=ElectronPacketGap::photon_continuation;tally(7,1);}
                return;
            }
        }
        ++packet.advances;tally(2,1);
        const auto coin=uniform();
        const auto* cuts=exact?g->cuts:s->cuts;
        if(coin<Probability{cuts[0]}) {
            p=p+(pdg==11?uniform():1.f)*delta;
            packet.deposit_position={p.x,p.y,p.z};packet.status=ElectronPacketStatus::deposited;
            state();tally(5,1);return;
        }
        p=endpoint;
        unsigned channel=1;
        while(channel<3 && coin>=Probability{cuts[channel]})++channel;
        if(!(f[channel]>0))return invalid();
        energy*=f[channel];
        if(channel==1) {
            if(exact) {
                cursor=g->next;
                if(cursor==-2){if(pdg!=11)return invalid();d=rotate(target,project(original,g->postdir));}
                else if(cursor<0)return invalid();
            }else d=rotate(sample_frame,s->post);
        }else {
            cursor=exact?g->child[channel-2]:s->child[channel-2];
            if(cursor<0 || std::uint32_t(cursor)>=m.graph_count)return invalid();
            if(m.graph[cursor].pdg==22)++packet.photon_children;else ++packet.electron_children;
            if(!exact){original=basis(s->source);target=sample_frame;}
        }
    }
    return invalid(); // iteration cap is a failure, never local deposition
}
// This overload needs only the physical material identity; it never binds a
// material continuation record on leaving homogeneous joint support.
template<class Uniform,class Tally>
inline void transport_joint_independent(ElectronEnergyPacket& packet,
    ElectronJointPilotView pilot,const ElectronCtGeometry& geometry,Uniform& uniform,Tally& tally){
    ElectronMaterialIdentity identity{};identity.section=packet.cursor.section;
    identity.density_g_cm3=packet.cursor.physical_density_g_cm3;
    transport_joint_pilot(packet,pilot,identity,geometry,uniform,tally);
}

